// scripts/tooling/check-derived-views.mjs
//
// org/TASKS.md must agree with the records under org/tasks/.
//
// The records are canonical; TASKS.md is derived and regenerated by the EOS
// tooling. Nothing checked that the derived view had actually BEEN regenerated,
// and it drifted: four consecutive records read `done` with a named owner while
// the table still reported them `proposed | unassigned`, and two newer records
// were missing from it entirely. `npm run lint` stayed green throughout, so the
// drift surfaced in review, by eye, which is exactly the thing a gate is for.
//
// The drift had a root cause worth naming, because it makes the failure mode
// non-obvious: `python -m tools.eos task views` — the command both derived files
// name in their own headers — resolves its repo root from the module's own
// location, not the working directory. Run from a venture it reports
// `{"regenerated": [...]}`, exits 0, and regenerates the EOS checkout's views
// rather than the venture's. Filed as friction in docs/EOS_FEEDBACK.md.
//
// WHAT THIS DOES NOT DO. It does not re-derive TASKS.md. A checker carrying its
// own copy of a generator's rule is how the two come to disagree, and the EOS's
// own `build_views` docstring says so in as many words. This compares only the
// five columns that are a direct projection of five named record fields, and on
// a mismatch it tells you to run the generator. It has no opinion about
// formatting, ordering, prose, or org/STATE.md, all of which belong to the
// generator alone.
//
// Dependency-free, per WG-WEB-013. Run by `npm run lint`; exits non-zero on
// drift.

import { readFileSync, existsSync, readdirSync } from "fs";
import { dirname, join } from "path";
import { fileURLToPath } from "url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const TASKS_DIR = join(ROOT, "org", "tasks");
const VIEW = join(ROOT, "org", "TASKS.md");

/** The five columns, in table order, and the record field each comes from. */
const COLUMNS = [
  ["id", "id"],
  ["mode", "mode"],
  ["tier", "tier_ruled"],
  ["status", "status"],
  ["owner", "owner_session"],
];

const failures = [];

/** Parse the table body into id -> {column: cell}. */
function readView(text) {
  const rows = new Map();
  for (const line of text.split(/\r?\n/)) {
    if (!/^\|\s*T-\d+\s*\|/.test(line)) continue;
    // Drop the leading and trailing pipe before splitting, so an empty first
    // and last cell do not shift every column by one.
    const cells = line.replace(/^\|/, "").replace(/\|\s*$/, "").split("|").map((c) => c.trim());
    if (cells.length !== COLUMNS.length) {
      failures.push(`org/TASKS.md: row for ${cells[0]} has ${cells.length} cells, expected ${COLUMNS.length}`);
      continue;
    }
    rows.set(cells[0], Object.fromEntries(COLUMNS.map(([name], i) => [name, cells[i]])));
  }
  return rows;
}

if (!existsSync(VIEW)) {
  failures.push("org/TASKS.md is missing");
} else if (!existsSync(TASKS_DIR)) {
  failures.push("org/tasks/ is missing");
} else {
  const view = readView(readFileSync(VIEW, "utf-8"));

  const records = new Map();
  for (const name of readdirSync(TASKS_DIR).sort()) {
    if (!/^T-\d+\.json$/.test(name)) continue;
    let doc;
    try {
      doc = JSON.parse(readFileSync(join(TASKS_DIR, name), "utf-8"));
    } catch (e) {
      // Reported and skipped, never guessed at: a record we cannot read is a
      // problem in its own right, and pretending it said something would be
      // worse than saying we could not read it.
      failures.push(`org/tasks/${name}: not valid JSON (${e.message})`);
      continue;
    }
    records.set(String(doc.id ?? name.replace(/\.json$/, "")), doc);
  }

  for (const [id, record] of records) {
    const row = view.get(id);
    if (!row) {
      failures.push(`${id} has a record but no row in org/TASKS.md`);
      continue;
    }
    for (const [column, field] of COLUMNS) {
      const expected = String(record[field] ?? "");
      if (row[column] !== expected) {
        failures.push(`${id}: org/TASKS.md says ${column}="${row[column]}", the record says ${field}="${expected}"`);
      }
    }
  }

  for (const id of view.keys()) {
    if (!records.has(id)) failures.push(`${id} has a row in org/TASKS.md but no record under org/tasks/`);
  }
}

if (failures.length > 0) {
  console.error("derived views: org/TASKS.md disagrees with the records under org/tasks/.\n");
  for (const f of failures) console.error(`  ${f}`);
  console.error(
    "\nThe records are canonical. Do NOT hand-edit org/TASKS.md — it is derived." +
      "\nRegenerate it (integrator only). Note that `python -m tools.eos task views`" +
      "\nregenerates the EOS checkout's own views, not this repo's; from this repo root," +
      "\nwith PYTHONPATH pointing at the EOS checkout, run:" +
      "\n\n  python -c \"from tools.eos import taskops; print(taskops.render_views('.'))\"\n",
  );
  process.exit(1);
}

console.log(`derived views: org/TASKS.md matches all ${readView(readFileSync(VIEW, "utf-8")).size} records.`);
